using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;
public static class TwoDomeCapture {
 public static object Before()=>Run("Before");public static object After()=>Run("After");
 static object Run(string prefix){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");var origin=new Vector3(-22,-82,18);var output=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-08_B5_TwoDomeGuidance/"));Directory.CreateDirectory(output);var players=s.GetRootGameObjects().Where(g=>g.name.StartsWith("Player")).SelectMany(g=>g.GetComponentsInChildren<Renderer>()).ToArray();var was=players.Select(r=>r.enabled).ToArray();foreach(var r in players)r.enabled=false;
 var shots=new[]{new{name="CredentialDetail",p=new Vector3(-3.9f,1.65f,.35f),t=new Vector3(-5.8f,1.3f,-.3f),fov=65f},new{name="EvidenceDetail",p=new Vector3(2.1f,1.7f,-2.4f),t=new Vector3(4.35f,1.15f,-4.35f),fov=62f},new{name="MonitorFront",p=new Vector3(-.15f,1.40f,3.0f),t=new Vector3(-1.25f,1.22f,4.20f),fov=53f},new{name="MonitorBack",p=new Vector3(-2.6f,1.65f,4.9f),t=new Vector3(-1.25f,1.16f,4.2f),fov=65f},new{name="FromLab",p=new Vector3(1.1f,1.7f,-4.8f),t=new Vector3(-.5f,1.7f,4.3f),fov=82f},new{name="Operations",p=new Vector3(3.2f,1.7f,1.0f),t=new Vector3(-1,1.3f,4.2f),fov=78f},new{name="SouthServices",p=new Vector3(-3,1.7f,2.8f),t=new Vector3(-1.5f,1.4f,-4.3f),fov=80f},new{name="WallDetail",p=new Vector3(0,1.6f,2.8f),t=new Vector3(0,2.25f,5.4f),fov=70f},new{name="Overview",p=new Vector3(1.5f,5.4f,-2.5f),t=new Vector3(-.4f,.4f,1.4f),fov=90f},new{name="EntryBack",p=new Vector3(0,1.7f,1.2f),t=new Vector3(1.5f,1.3f,-6),fov=84f}};
 try{foreach(var shot in shots){var g=new GameObject("Temporary_C02_Review");var cam=g.AddComponent<Camera>();cam.transform.position=origin+shot.p;cam.transform.LookAt(origin+shot.t);cam.fieldOfView=shot.fov;cam.nearClipPlane=.035f;cam.farClipPlane=200;cam.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var old=RenderTexture.active;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(output+prefix+"_"+shot.name+".png",tex.EncodeToPNG());RenderTexture.active=old;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}finally{for(int i=0;i<players.Length;i++)players[i].enabled=was[i];EditorSceneManager.OpenScene(s.path);}return new{prefix,images=shots.Length};}
}
